import sys

def find_winner(N, S, stacks):
    def calculate_grundy(stack):
        if not stack:
            return 0
        grundy = 0
        for i in range(len(stack)):
            if stack[i] == '0':
                grundy ^= i + 1
                break
        else:
            for i in range(len(stack)):
                if stack[i] == '1':
                    grundy ^= i + 1
                    break
        return grundy

    total_grundy = 0
    for stack in stacks:
        total_grundy ^= calculate_grundy(stack)

    if total_grundy == 0:
        return "Dum" if S == "Dee" else "Dee"
    else:
        return S

def main():
    import sys
    input = sys.stdin.read().splitlines()
    index = 0
    T = int(input[index])
    index += 1
    results = []
    for _ in range(T):
        N, S = input[index].split()
        N = int(N)
        index += 1
        stacks = input[index:index + N]
        index += N
        results.append(find_winner(N, S, stacks))
    print("\n".join(results))

if __name__ == "__main__":
    main()
